<div class="message-list" @onscroll="HandleScroll">
    @if (IsLoadingMore)
    {
        <div class="loading-indicator">Loading older messages…</div>
    }

    @foreach (var msg in Messages)
    {
        <MessageItem Message="msg"
                     ReplyCount="GetReplyCount(msg.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
    }

    @if (Messages.Count == 0 && !IsLoadingMore)
    {
        <div class="empty-state">No messages yet. Start the conversation!</div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId)
    {
        var summary = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);
        return summary?.ReplyCount ?? 0;
    }

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top triggers load more via JS interop would be ideal,
        // but for a server-side approach we provide a manual trigger
        // The actual scroll detection relies on JS — see the load-more button fallback
    }
}

