@using sv_d67db6612b4f44778988c654656b8f9f.Models

<div class="message-area">
    <div class="area-header">
        <div>
            <h4># @Channel.Name</h4>
            <span class="area-description">@Channel.Description</span>
        </div>
    </div>

    @if (HasMoreMessages)
    {
        <div class="load-more-bar">
            <button class="load-more-btn" @onclick="OnLoadMore" disabled="@IsLoadingMore">
                @(IsLoadingMore ? "Loading…" : "↑ Load older messages")
            </button>
        </div>
    }

    <MessageList Messages="Messages"
                 ThreadSummaries="ThreadSummaries"
                 IsLoadingMore="IsLoadingMore"
                 OnLoadMore="OnLoadMore"
                 OnOpenThread="OnOpenThread"
                 OnReact="OnReact" />

    <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                  ButtonLabel="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
}

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background-color: #313338;
    overflow: hidden;
}

.area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-shrink: 0;
}

.area-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 700;
}

.area-description {
    font-size: 0.8rem;
    color: #72767d;
}

.load-more-bar {
    text-align: center;
    padding: 6px;
    flex-shrink: 0;
}

.load-more-btn {
    background: none;
    border: 1px solid #3f4147;
    color: #00a8fc;
    font-size: 0.8rem;
    padding: 4px 14px;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color 0.15s;
}

.load-more-btn:hover:not(:disabled) {
    background-color: rgba(0, 168, 252, 0.1);
}

.load-more-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

