    display: flex;
    align-items: baseline;
    gap: 6px;
    margin-bottom: 1px;
}

.reply-author {
    font-weight: 600;
    font-size: 0.82rem;
    color: #f2f3f5;
}

.reply-time {
    font-size: 0.7rem;
    color: #72767d;
}

.reply-content {
    font-size: 0.85rem;
    color: #dcddde;
    line-height: 1.3;
}

