+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-layout">
+    <div class="chat-sidebar">
+        <ChannelSidebar Channels="_channels"
+                        ActiveChannelId="_activeChannelId"
+                        OnChannelSelected="SelectChannel" />
+    </div>
+
+    <div class="chat-main @(_threadOpen ? "" : "expanded")">
+        @if (_activeChannel is not null)
+        {
+            <MessageArea Channel="_activeChannel"
+                         Messages="_messages"
+                         ThreadSummaries="_threadSummaries"
+                         IsLoadingMore="_isLoadingMore"
+                         HasMoreMessages="_hasMoreMessages"
+                         OnLoadMore="LoadMoreMessages"
+                         OnOpenThread="OpenThread"
+                         OnReact="HandleReaction"
+                         OnSendMessage="SendMessage" />
+        }
+    </div>
+
+    @if (_threadOpen)
+    {
+        <div class="chat-thread">
+            <ThreadPanel RootMessage="_threadRootMessage"
+                         ThreadMessages="_threadMessages"
+                         OnClose="CloseThread"
+                         OnSendReply="SendThreadReply" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> _channels = [];
+    private List<Message> _messages = [];
+    private List<ThreadSummary> _threadSummaries = [];
+    private List<Message> _threadMessages = [];
+
+    private Channel? _activeChannel;
+    private int _activeChannelId;
+    private Message? _threadRootMessage;
+    private bool _threadOpen;
+    private bool _isLoadingMore;
+    private bool _hasMoreMessages;
+
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _channels = await ChatService.GetChannelsAsync();
+        if (_channels.Count > 0)
+        {
+            await SelectChannel(_channels[0]);
+        }
+    }
+
+    private async Task SelectChannel(Channel channel)
+    {
+        _activeChannel = channel;
+        _activeChannelId = channel.Id;
+        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
+        _hasMoreMessages = _messages.Count >= PageSize;
+        _threadSummaries = BuildThreadSummaries(_messages);
+
+        CloseThreadInternal();
+        await ChatService.MarkChannelReadAsync(channel.Id);
+
+        // Refresh channels to update unread counts
+        _channels = await ChatService.GetChannelsAsync();
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (_activeChannel is null || _isLoadingMore) return;
+
+        _isLoadingMore = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messages.Count, PageSize);
+        _hasMoreMessages = older.Count >= PageSize;
+        _messages.InsertRange(0, older);
+        _threadSummaries = BuildThreadSummaries(_messages);
+        _isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (_activeChannel is null) return;
+        var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
+        _messages.Add(msg);
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
+        if (_threadRootMessage is null) return;
+
+        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
+        _threadOpen = true;
+    }
+
+    private void CloseThread() => CloseThreadInternal();
+
+    private void CloseThreadInternal()
+    {
+        _threadOpen = false;
+        _threadRootMessage = null;
+        _threadMessages = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (_activeChannel is null || _threadRootMessage is null) return;
+
+        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _threadRootMessage.Id);
+        _threadMessages.Add(reply);
+
+        // Update thread summary count
+        _threadSummaries = BuildThreadSummaries(_messages, _threadRootMessage.Id, _threadMessages.Count);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Refresh messages to show updated reactions
+        if (_activeChannel is not null)
+        {
+            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, _messages.Count);
+        }
+    }
+
+    private static List<ThreadSummary> BuildThreadSummaries(List<Message> messages, int? updatedThreadId = null, int? updatedCount = null)
+    {
+        var replies = messages.Where(m => m.ReplyToId.HasValue).ToList();
+        var summaries = replies
+            .GroupBy(m => m.ReplyToId!.Value)
+            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
+            .ToList();
+
+        if (updatedThreadId.HasValue && updatedCount.HasValue)
+        {
+            var existing = summaries.FirstOrDefault(s => s.RootMessageId == updatedThreadId.Value);
+            if (existing is not null)
+            {
+                summaries.Remove(existing);
+            }
+            summaries.Add(new ThreadSummary(updatedThreadId.Value, updatedCount.Value, DateTime.UtcNow));
+        }
+
+        return summaries;
+    }
+}
+

