toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    background-color: #313338;
    color: #dcddde;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    min-width: 0;
}

.chat-main.expanded {
    /* Takes remaining space when thread is closed */
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

::deep * {
    box-sizing: border-box;
}

